/* @lc app=leetcode id=3614 lang=kotlin */ class Solution { fun processStr(s: String, k: Long): Char = s.runningFold(0L) { l, c -> if (c in 'a'..'z') l + 1 else if (c == '*') maxOf(0L, l - 1) else if (c == '#') 2 * l else l }.let { lens -> if (k >= lens.last()) '.' else (s.length - 1 downTo 0).fold(k to (null as Char?)) { (kk, ans), i -> if (ans != null) kk to ans else s[i].let { c -> lens[i + 1].let { li -> lens[i].let { lp -> if (c in 'a'..'z') (if (kk == li - 1) kk to c else kk to null) else if (c == '*') kk to null else if (c == '#') (if (kk >= lp) kk - lp else kk) to null else (li - 1 - kk) to null } } } }.second ?: '.' } }